import{_ as i,c as a,o,a2 as t}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"使用教學","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/usage.md","filePath":"zh-TW/guide/usage.md","lastUpdated":1793163976000}'),r={name:"zh-TW/guide/usage.md"};function e(n,l,d,s,h,g){return o(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="使用教學" tabindex="-1">使用教學 <a class="header-anchor" href="#使用教學" aria-label="Permalink to &quot;使用教學&quot;">​</a></h1><h2 id="開啟壓縮檔" tabindex="-1">開啟壓縮檔 <a class="header-anchor" href="#開啟壓縮檔" aria-label="Permalink to &quot;開啟壓縮檔&quot;">​</a></h2><h3 id="雙擊開啟" tabindex="-1">雙擊開啟 <a class="header-anchor" href="#雙擊開啟" aria-label="Permalink to &quot;雙擊開啟&quot;">​</a></h3><p>NueZip 會註冊為所有受支援壓縮檔格式的預設處理程式。只要雙擊任何壓縮檔檔案（<code>.zip</code>、<code>.rar</code>、<code>.7z</code>、<code>.tar</code>、<code>.gz</code>、<code>.bz2</code>、<code>.xz</code>、<code>.zst</code>），即可在 NueZip 的主視窗中開啟它。</p><h3 id="使用-nuezip-開啟-finder-右鍵選單" tabindex="-1">使用 NueZip 開啟（Finder 右鍵選單） <a class="header-anchor" href="#使用-nuezip-開啟-finder-右鍵選單" aria-label="Permalink to &quot;使用 NueZip 開啟（Finder 右鍵選單）&quot;">​</a></h3><p>右鍵點擊任何壓縮檔，並從選單中選擇 <strong>使用 NueZip 開啟</strong>。Finder 擴充功能也提供快速動作：</p><ul><li><strong>在此解壓縮</strong> — 將壓縮檔內容解壓縮到目前資料夾</li><li><strong>解壓縮到「資料夾名稱/」</strong> — 解壓縮到具名的子資料夾</li><li><strong>壓縮為 ZIP</strong> — 將選取的檔案/資料夾壓縮成 ZIP 壓縮檔</li><li><strong>使用 NueZip 開啟</strong> — 在主瀏覽視窗中開啟</li></ul><h3 id="拖放到匣子-tray" tabindex="-1">拖放到匣子（Tray） <a class="header-anchor" href="#拖放到匣子-tray" aria-label="Permalink to &quot;拖放到匣子（Tray）&quot;">​</a></h3><p>將任何壓縮檔拖曳到 NueZip 的選單列圖示上，即可在拖放面板中快速開啟以便立即存取。您也可以將檔案拖曳到匣子圖示上進行壓縮。</p><h2 id="解壓縮檔" tabindex="-1">解壓縮檔 <a class="header-anchor" href="#解壓縮檔" aria-label="Permalink to &quot;解壓縮檔&quot;">​</a></h2><h3 id="基本解壓縮" tabindex="-1">基本解壓縮 <a class="header-anchor" href="#基本解壓縮" aria-label="Permalink to &quot;基本解壓縮&quot;">​</a></h3><ol><li>在 NueZip 中開啟一個壓縮檔</li><li>點擊工具列中的 <strong>解壓縮</strong> 按鈕</li><li>選擇目的地資料夾</li><li>點擊 <strong>解壓縮</strong></li></ol><h3 id="從-finder-快速解壓縮" tabindex="-1">從 Finder 快速解壓縮 <a class="header-anchor" href="#從-finder-快速解壓縮" aria-label="Permalink to &quot;從 Finder 快速解壓縮&quot;">​</a></h3><p>在 Finder 中右鍵點擊壓縮檔，並選擇下列其中一項快速動作：</p><ul><li><strong>在此解壓縮</strong> — 直接解壓縮到目前資料夾</li><li><strong>解壓縮到「[壓縮檔名稱]/」</strong> — 解壓縮到具名的子資料夾，讓檔案整齊有序</li></ul><h3 id="使用密碼解壓縮" tabindex="-1">使用密碼解壓縮 <a class="header-anchor" href="#使用密碼解壓縮" aria-label="Permalink to &quot;使用密碼解壓縮&quot;">​</a></h3><p>對於受密碼保護的壓縮檔，NueZip 會提示輸入密碼。內建的密碼管理員可以將憑證安全地儲存在您的本機鑰匙圈中，供日後使用。</p><h2 id="壓縮檔" tabindex="-1">壓縮檔 <a class="header-anchor" href="#壓縮檔" aria-label="Permalink to &quot;壓縮檔&quot;">​</a></h2><h3 id="建立新壓縮檔" tabindex="-1">建立新壓縮檔 <a class="header-anchor" href="#建立新壓縮檔" aria-label="Permalink to &quot;建立新壓縮檔&quot;">​</a></h3><ol><li>在 NueZip 的主視窗中選取檔案或資料夾</li><li>點擊工具列中的 <strong>壓縮</strong> 按鈕</li><li>選擇壓縮檔格式（ZIP、7z、TAR、GZIP 等）</li><li>設定壓縮選項（層級、加密方式）</li><li>點擊 <strong>壓縮</strong></li></ol><h3 id="從-finder-壓縮" tabindex="-1">從 Finder 壓縮 <a class="header-anchor" href="#從-finder-壓縮" aria-label="Permalink to &quot;從 Finder 壓縮&quot;">​</a></h3><p>在 Finder 中右鍵點擊檔案/資料夾，並選擇 <strong>使用 NueZip 壓縮</strong>：</p><ul><li><strong>壓縮為 ZIP</strong> — 快速建立 ZIP 壓縮檔</li><li><strong>使用選項壓縮</strong> — 以進階設定開啟 NueZip</li></ul><h3 id="透過拖放壓縮" tabindex="-1">透過拖放壓縮 <a class="header-anchor" href="#透過拖放壓縮" aria-label="Permalink to &quot;透過拖放壓縮&quot;">​</a></h3><p>將檔案拖曳到 NueZip 的選單列匣子圖示上，即可快速建立 ZIP 壓縮檔。</p><h2 id="批次操作" tabindex="-1">批次操作 <a class="header-anchor" href="#批次操作" aria-label="Permalink to &quot;批次操作&quot;">​</a></h2><h3 id="批次壓縮" tabindex="-1">批次壓縮 <a class="header-anchor" href="#批次壓縮" aria-label="Permalink to &quot;批次壓縮&quot;">​</a></h3><ol><li>在 NueZip 中選取多個項目</li><li>從工具列或檔案選單中選擇 <strong>批次壓縮</strong></li><li>每個項目都會被壓縮成獨立的壓縮檔</li></ol><h3 id="批次解壓縮" tabindex="-1">批次解壓縮 <a class="header-anchor" href="#批次解壓縮" aria-label="Permalink to &quot;批次解壓縮&quot;">​</a></h3><ol><li>在 NueZip 中選取多個壓縮檔</li><li>從工具列或檔案選單中選擇 <strong>批次解壓縮</strong></li><li>所有壓縮檔都會同時解壓縮</li></ol><h3 id="批次轉換" tabindex="-1">批次轉換 <a class="header-anchor" href="#批次轉換" aria-label="Permalink to &quot;批次轉換&quot;">​</a></h3><ol><li>選取一個或多個壓縮檔</li><li>選擇 <strong>轉換</strong> → 選取目標格式</li><li>NueZip 會將每個壓縮檔重新壓縮成所選格式</li></ol><h3 id="批次加密" tabindex="-1">批次加密 <a class="header-anchor" href="#批次加密" aria-label="Permalink to &quot;批次加密&quot;">​</a></h3><ol><li>選取多個 ZIP 壓縮檔</li><li>選擇 <strong>批次加密</strong></li><li>設定密碼 — 所有選取的壓縮檔都會受到密碼保護</li></ol><h2 id="格式轉換" tabindex="-1">格式轉換 <a class="header-anchor" href="#格式轉換" aria-label="Permalink to &quot;格式轉換&quot;">​</a></h2><p>在任意受支援的格式之間轉換壓縮檔：</p><ol><li>開啟一個壓縮檔</li><li>點擊工具列中的 <strong>轉換</strong></li><li>選取目標格式（例如 RAR → ZIP、7z → TAR.GZ）</li><li>選擇輸出位置</li><li>點擊 <strong>轉換</strong></li></ol><h2 id="壓縮檔修復" tabindex="-1">壓縮檔修復 <a class="header-anchor" href="#壓縮檔修復" aria-label="Permalink to &quot;壓縮檔修復&quot;">​</a></h2><p>針對損毀的 RAR 或 ZIP 壓縮檔：</p><ol><li>開啟損毀的壓縮檔</li><li>點擊工具列中的 <strong>修復</strong></li><li>NueZip 會嘗試重建壓縮檔資料</li><li>修復後的壓縮檔會另存為新檔案</li></ol><h2 id="壓縮檔搜尋" tabindex="-1">壓縮檔搜尋 <a class="header-anchor" href="#壓縮檔搜尋" aria-label="Permalink to &quot;壓縮檔搜尋&quot;">​</a></h2><p>在壓縮檔中尋找特定檔案：</p><ol><li>點擊工具列中的 <strong>搜尋</strong> 按鈕</li><li>輸入檔名模式</li><li>NueZip 會搜尋開啟的壓縮檔中的所有項目</li><li>結果會顯示完整路徑，方便快速導覽</li></ol><h2 id="效能測試" tabindex="-1">效能測試 <a class="header-anchor" href="#效能測試" aria-label="Permalink to &quot;效能測試&quot;">​</a></h2><p>測試您系統的壓縮效能：</p><ol><li>前往 <strong>工具 → 效能測試</strong></li><li>NueZip 會使用各種格式與設定執行壓縮測試</li><li>結果會顯示每種格式的壓縮速度（MB/s）與壓縮比</li><li>可用此來比較不同壓縮方法之間的效能</li></ol><h2 id="多分割卷-split-壓縮檔" tabindex="-1">多分割卷（Split）壓縮檔 <a class="header-anchor" href="#多分割卷-split-壓縮檔" aria-label="Permalink to &quot;多分割卷（Split）壓縮檔&quot;">​</a></h2><p>為大型資料建立分割壓縮檔：</p><ol><li>在壓縮過程中，啟用 <strong>分割為多個卷</strong></li><li>選擇卷大小（例如 100 MB、650 MB、4.7 GB，或自訂）</li><li>NueZip 會建立編號的分割檔（<code>.zip.001</code>、<code>.zip.002</code> 等）</li><li>若要解壓縮，請開啟第一個分割檔 — NueZip 會自動載入其餘部分</li></ol><ul><li><strong>密碼</strong>：為加密壓縮檔提供密碼</li><li><strong>包裝進資料夾</strong>：若壓縮檔沒有單一根目錄，自動建立根資料夾</li><li><strong>完成後開啟</strong>：解壓縮完成後在 Finder 中顯示解壓出的檔案</li><li><strong>保留損壞檔案</strong>：保留錯誤發生前已解壓出的任何檔案（用於部分復原）</li><li><strong>更新模式</strong>：選擇如何處理現有檔案（覆寫、跳過、重新命名）</li></ul><h3 id="批次解壓縮-1" tabindex="-1">批次解壓縮 <a class="header-anchor" href="#批次解壓縮-1" aria-label="Permalink to &quot;批次解壓縮&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批次解壓縮</strong></li><li>點擊 <strong>加入檔案...</strong> 選取壓縮檔</li><li>選擇目的地資料夾</li><li>可選擇啟用 <strong>解壓縮後刪除來源檔案</strong></li><li>點擊 <strong>開始</strong></li></ol><h2 id="建立壓縮檔" tabindex="-1">建立壓縮檔 <a class="header-anchor" href="#建立壓縮檔" aria-label="Permalink to &quot;建立壓縮檔&quot;">​</a></h2><h3 id="壓縮檔案" tabindex="-1">壓縮檔案 <a class="header-anchor" href="#壓縮檔案" aria-label="Permalink to &quot;壓縮檔案&quot;">​</a></h3><ol><li>點擊工具列中的 <strong>壓縮</strong> 按鈕</li><li>選取要壓縮的檔案（或將它們拖放進視窗）</li><li>選擇 <strong>壓縮檔格式</strong>：ZIP、7Z、TAR、GZIP、BZIP2</li><li>設定 <strong>壓縮方式</strong> 與層級</li><li>設定 <strong>儲存位置</strong> 與壓縮檔名稱</li><li>可選擇設定 <strong>密碼</strong> 進行加密</li><li>可選擇設定 <strong>分割大小</strong> 以建立多分割卷壓縮檔</li><li>點擊 <strong>壓縮</strong></li></ol><h3 id="將檔案加入現有壓縮檔" tabindex="-1">將檔案加入現有壓縮檔 <a class="header-anchor" href="#將檔案加入現有壓縮檔" aria-label="Permalink to &quot;將檔案加入現有壓縮檔&quot;">​</a></h3><ol><li>在 NueZip 中開啟現有的壓縮檔</li><li>點擊工具列中的 <strong>加入檔案</strong></li><li>選取要加入的檔案</li><li>點擊 <strong>加入</strong></li></ol><h2 id="批次操作-1" tabindex="-1">批次操作 <a class="header-anchor" href="#批次操作-1" aria-label="Permalink to &quot;批次操作&quot;">​</a></h2><h3 id="批次壓縮-1" tabindex="-1">批次壓縮 <a class="header-anchor" href="#批次壓縮-1" aria-label="Permalink to &quot;批次壓縮&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批次壓縮</strong></li><li>點擊 <strong>選取檔案/資料夾...</strong> 選擇項目</li><li>每個選取的項目都會成為獨立的壓縮檔</li><li>設定輸出的 <strong>格式</strong>、<strong>儲存位置</strong> 與檔案命名前置詞</li><li>點擊 <strong>開始</strong></li></ol><h3 id="批次轉換格式" tabindex="-1">批次轉換格式 <a class="header-anchor" href="#批次轉換格式" aria-label="Permalink to &quot;批次轉換格式&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批次轉換格式</strong></li><li>點擊 <strong>加入檔案...</strong> 選取來源壓縮檔</li><li>選擇 <strong>目標格式</strong></li><li>可選擇啟用 <strong>轉換後刪除來源檔案</strong></li><li>點擊 <strong>開始</strong></li></ol><h3 id="批次加密-1" tabindex="-1">批次加密 <a class="header-anchor" href="#批次加密-1" aria-label="Permalink to &quot;批次加密&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批次加密</strong></li><li>點擊 <strong>加入檔案...</strong> 選取壓縮檔</li><li>輸入 <strong>密碼</strong></li><li>點擊 <strong>加密</strong></li></ol><h2 id="進階功能" tabindex="-1">進階功能 <a class="header-anchor" href="#進階功能" aria-label="Permalink to &quot;進階功能&quot;">​</a></h2><h3 id="壓縮檔修復-1" tabindex="-1">壓縮檔修復 <a class="header-anchor" href="#壓縮檔修復-1" aria-label="Permalink to &quot;壓縮檔修復&quot;">​</a></h3><p>修復損毀或受損的壓縮檔：</p><ol><li>選取受損的壓縮檔</li><li>前往 <strong>工具 → 修復壓縮檔</strong></li><li>NueZip 會掃描檔頭、重建目錄，並修復資料區塊</li><li>檢視修復結果</li></ol><h3 id="格式轉換-1" tabindex="-1">格式轉換 <a class="header-anchor" href="#格式轉換-1" aria-label="Permalink to &quot;格式轉換&quot;">​</a></h3><p>在格式之間轉換壓縮檔：</p><ol><li>開啟壓縮檔或選取檔案</li><li>前往 <strong>檔案 → 轉換格式</strong></li><li>選擇目標格式與壓縮層級</li><li>可選擇刪除原始檔案</li><li>點擊 <strong>轉換</strong></li></ol><h3 id="密碼管理員" tabindex="-1">密碼管理員 <a class="header-anchor" href="#密碼管理員" aria-label="Permalink to &quot;密碼管理員&quot;">​</a></h3><p>NueZip 會將壓縮檔密碼安全地儲存在您的本機鑰匙圈中：</p><ol><li>前往 <strong>工具 → 密碼管理員</strong></li><li>檢視所有已儲存的密碼</li><li>新增、編輯或刪除項目</li><li>開啟相符的加密壓縮檔時，密碼會自動套用</li></ol><h3 id="效能測試-1" tabindex="-1">效能測試 <a class="header-anchor" href="#效能測試-1" aria-label="Permalink to &quot;效能測試&quot;">​</a></h3><p>測試您系統的壓縮效能：</p><ol><li>前往 <strong>工具 → 效能測試</strong></li><li>選擇測試檔案（或使用預設檔案）</li><li>點擊 <strong>測試</strong></li><li>檢視包含壓縮/解壓縮速度與評級的結果</li></ol><h3 id="壓縮檔搜尋-1" tabindex="-1">壓縮檔搜尋 <a class="header-anchor" href="#壓縮檔搜尋-1" aria-label="Permalink to &quot;壓縮檔搜尋&quot;">​</a></h3><p>在壓縮檔中尋找檔案：</p><ol><li>開啟壓縮檔</li><li>按下 <code>Cmd+F</code> 或點擊搜尋圖示</li><li>輸入檔名，可選擇是否區分大小寫或比對整個單字</li><li>瀏覽搜尋結果並點擊以導覽</li></ol><h2 id="鍵盤快捷鍵" tabindex="-1">鍵盤快捷鍵 <a class="header-anchor" href="#鍵盤快捷鍵" aria-label="Permalink to &quot;鍵盤快捷鍵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷鍵</th><th>動作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>開啟壓縮檔</td></tr><tr><td><code>Cmd+N</code></td><td>新建壓縮檔</td></tr><tr><td><code>Cmd+E</code></td><td>解壓縮</td></tr><tr><td><code>Cmd+F</code></td><td>在壓縮檔中尋找</td></tr><tr><td><code>Cmd+,</code></td><td>開啟設定</td></tr><tr><td><code>Cmd+W</code></td><td>關閉視窗</td></tr><tr><td><code>Cmd+Q</code></td><td>結束應用程式</td></tr><tr><td><code>Cmd+↑</code></td><td>上一層</td></tr><tr><td><code>Cmd+→</code></td><td>向前</td></tr></tbody></table><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>透過 <strong>NueZip → 設定</strong> 或按下 <code>Cmd+,</code> 存取設定：</p><ul><li><strong>一般</strong>：語言、登入時啟動、外觀主題</li><li><strong>壓縮</strong>：預設格式、壓縮層級、分割大小</li><li><strong>解壓縮</strong>：預設目的地、包裝行為、衝突處理</li><li><strong>資料夾存取</strong>：管理資料夾權限與書籤</li><li><strong>進階</strong>：硬體加速、執行緒數量、暫存目錄</li><li><strong>隱私</strong>：資料蒐集偏好</li></ul>',85)])])}const b=i(r,[["render",e]]);export{u as __pageData,b as default};
